def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def minWidthAfterCut(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    depth = [0] * n
    pos = [0] * n
    idx = [0] * n
    pos[0] = 1
    levels = []
    for k in range(n):
        d = depth[k]
        if d == len(levels):
            levels.append([])
        idx[k] = len(levels[d])
        levels[d].append(k)
        if left[k] != -1:
            depth[left[k]] = d + 1
            pos[left[k]] = 2 * pos[k]
        if right[k] != -1:
            depth[right[k]] = d + 1
            pos[right[k]] = 2 * pos[k] + 1
    H = len(levels)
    W = [pos[lv[-1]] - pos[lv[0]] + 1 for lv in levels]
    prefix = [0] * (H + 1)          # prefix[d] = widest of levels 0..d-1
    for d in range(H):
        prefix[d + 1] = max(prefix[d], W[d])
    suffix = [0] * (H + 1)          # suffix[d] = widest of levels d..H-1
    for d in range(H - 1, -1, -1):
        suffix[d] = max(suffix[d + 1], W[d])
    before = []                     # before[d][i] = children of the first i nodes of level d
    for d in range(H):
        acc = [0]
        for k in levels[d]:
            acc.append(acc[-1] + (left[k] != -1) + (right[k] != -1))
        before.append(acc)
    best = None
    for v in range(1, n):
        d = depth[v]
        a = b = idx[v]
        cur = prefix[d]
        lvl = d
        while lvl < H:
            if a > b:
                cur = max(cur, suffix[lvl])
                break
            lv = levels[lvl]
            m = len(lv)
            if a > 0 and b < m - 1:
                w = W[lvl]
            elif a > 0:
                w = pos[lv[a - 1]] - pos[lv[0]] + 1
            elif b < m - 1:
                w = pos[lv[-1]] - pos[lv[b + 1]] + 1
            else:
                w = 0
            cur = max(cur, w)
            a, b = before[lvl][a], before[lvl][b + 1] - 1
            lvl += 1
        if best is None or cur < best:
            best = cur
    return best
